def list_calc_requests(api_key, status=None, requested_at_gte=None, requested_at_lte=None, expression_sha256=None, limit=None, cursor=None, order=None, **_extra):
    import json, os, datetime
    import time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0274000" if __import__("os").path.isdir("./environment_mix/0274000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _log_call(endpoint, api_key_id, status, started_monotonic, error_code=None):
        return

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _parse_stored_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        return _parse_rfc3339(s)

    def _encode_cursor(ts_iso, idv):
        import base64
        raw = (ts_iso or "") + "|" + (idv or "")
        return base64.urlsafe_b64encode(raw.encode("utf-8")).decode("ascii")

    def _decode_cursor(c):
        import base64
        if c is None:
            return None
        if not isinstance(c, str) or c == "":
            return None
        try:
            raw = base64.urlsafe_b64decode(c.encode("ascii")).decode("utf-8")
            parts = raw.split("|", 1)
            if len(parts) != 2:
                return None
            return {"ts": parts[0] or None, "id": parts[1] or None}
        except Exception:
            return None

    started = time.monotonic()

    # Validate api_key (explicit credential parameter). Must match api_keys.key_prefix OR api_keys.id.
    if not isinstance(api_key, str) or api_key == "":
        _log_call("list_calc_requests", None, "error", started, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key is required")

    api_keys = _load("api_keys.json")
    key_row = None
    for k in api_keys:
        if k.get("id") == api_key or k.get("key_prefix") == api_key:
            key_row = k
            break
    if key_row is None:
        _log_call("list_calc_requests", None, "error", started, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid API key.")

    if status is not None:
        if not isinstance(status, str) or status not in ["queued", "running", "succeeded", "failed", "rejected"]:
            _log_call("list_calc_requests", key_row.get("id"), "error", started, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status filter.")

    if requested_at_gte is not None:
        dt_gte = _parse_rfc3339(requested_at_gte)
        if dt_gte is None:
            _log_call("list_calc_requests", key_row.get("id"), "error", started, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "requested_at_gte must be an RFC3339 timestamp.")
    else:
        dt_gte = None

    if requested_at_lte is not None:
        dt_lte = _parse_rfc3339(requested_at_lte)
        if dt_lte is None:
            _log_call("list_calc_requests", key_row.get("id"), "error", started, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "requested_at_lte must be an RFC3339 timestamp.")
    else:
        dt_lte = None

    if dt_gte and dt_lte and dt_gte > dt_lte:
        _log_call("list_calc_requests", key_row.get("id"), "error", started, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "requested_at_gte must be <= requested_at_lte.")

    if expression_sha256 is not None:
        if not isinstance(expression_sha256, str) or len(expression_sha256) != 64:
            _log_call("list_calc_requests", key_row.get("id"), "error", started, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "expression_sha256 must be a hex-encoded SHA-256 (64 chars).")
        try:
            int(expression_sha256, 16)
        except Exception:
            _log_call("list_calc_requests", key_row.get("id"), "error", started, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "expression_sha256 must be hex.")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log_call("list_calc_requests", key_row.get("id"), "error", started, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")

    if order is None:
        order = "requested_at_desc"
    if not isinstance(order, str) or order not in ["requested_at_desc", "requested_at_asc"]:
        _log_call("list_calc_requests", key_row.get("id"), "error", started, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid order.")

    cur = _decode_cursor(cursor) if cursor is not None else None
    if cursor is not None and cur is None:
        _log_call("list_calc_requests", key_row.get("id"), "error", started, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid cursor.")

    calc_requests = _load("calc_requests.json")

    # Filter by ownership (must belong to calling API key)
    rows = []
    key_id = key_row.get("id")
    for r in calc_requests:
        if r.get("api_key_id") != key_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        if expression_sha256 is not None and r.get("expression_sha256") != expression_sha256:
            continue
        dt_req = _parse_stored_dt(r.get("requested_at"))
        if dt_req is None:
            continue
        if dt_gte is not None and dt_req < dt_gte:
            continue
        if dt_lte is not None and dt_req > dt_lte:
            continue
        rows.append(r)

    # Sort
    def _sort_key(r):
        dt_req = _parse_stored_dt(r.get("requested_at"))
        # fallback epoch
        if dt_req is None:
            dt_req = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (dt_req, r.get("id") or "")

    reverse = (order == "requested_at_desc")
    rows.sort(key=_sort_key, reverse=reverse)

    # Apply cursor (exclusive)
    if cur is not None:
        cur_dt = _parse_stored_dt(cur.get("ts")) if cur.get("ts") else None
        cur_id = cur.get("id")
        if cur_dt is not None and cur_id is not None:
            filtered = []
            for r in rows:
                dt_req = _parse_stored_dt(r.get("requested_at"))
                if dt_req is None:
                    continue
                if reverse:
                    # want items with (dt,id) < (cur_dt,cur_id)
                    if (dt_req, r.get("id") or "") < (cur_dt, cur_id):
                        filtered.append(r)
                else:
                    if (dt_req, r.get("id") or "") > (cur_dt, cur_id):
                        filtered.append(r)
            rows = filtered

    total = len(rows)
    page = rows[:limit]
    has_more = len(rows) > limit
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _encode_cursor(last.get("requested_at"), last.get("id"))

    _log_call("list_calc_requests", key_id, "ok", started, error_code=None)
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "order": order,
        },
    }

def get_calc_request(api_key, id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0274000" if __import__("os").path.isdir("./environment_mix/0274000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    started = time.monotonic()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    # --- Validation ---
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string")

    api_key_in = api_key.strip()
    req_id = id.strip()

    # --- Authenticate: parameter may be api_keys.id or key_prefix (client-visible only) ---
    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []

    key_row = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("id") == api_key_in or k.get("key_prefix") == api_key_in:
            key_row = k
            break
    if key_row is None:
        # log call attempt
        calc_requests_log = _load("calc_requests.json")
        if not isinstance(calc_requests_log, list):
            calc_requests_log = []
        # no dedicated request-log collection exists; do not mutate business tables for a read
        return _err("UNAUTHORIZED", "Invalid API key.")

    caller_key_id = key_row.get("id")

    # --- Load requests/results ---
    calc_requests = _load("calc_requests.json")
    if not isinstance(calc_requests, list):
        calc_requests = []
    calc_results = _load("calc_results.json")
    if not isinstance(calc_results, list):
        calc_results = []

    # --- Find request (must belong to caller; otherwise NOT_FOUND) ---
    req_row = None
    for r in calc_requests:
        if isinstance(r, dict) and r.get("id") == req_id:
            req_row = r
            break

    if req_row is None:
        return _err("NOT_FOUND", "Request not found.", id=req_id)

    if req_row.get("api_key_id") != caller_key_id:
        return _err("NOT_FOUND", "Request not found.", id=req_id)

    # --- Attach result if present ---
    res_row = None
    for cr in calc_results:
        if isinstance(cr, dict) and cr.get("request_id") == req_id:
            res_row = cr
            break

    # Build response (do not fabricate fields; only return stored data)
    out = {"request": req_row}
    if res_row is not None:
        out["result"] = res_row

    # Service dynamics: update api_keys.last_used_at for successful authorized read
    # (best-effort; if key missing/structure weird, return data without failing)
    try:
        # refresh key timestamps on any successful authenticated call
        changed = False
        for i, k in enumerate(api_keys):
            if isinstance(k, dict) and k.get("id") == caller_key_id:
                # updated_at always changes on mutation; last_used_at for reads
                api_keys[i] = dict(k)
                api_keys[i]["last_used_at"] = now_iso
                api_keys[i]["updated_at"] = now_iso
                changed = True
                break
        if changed:
            _save("api_keys.json", api_keys)
    except Exception:
        # unexpected IO issues should not crash; return data without raising
        return out

    return out

