def create_api_key(label, quota_daily_requests, quota_daily_compute_units, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0274000" if __import__("os").path.isdir("./environment_mix/0274000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    # Validate inputs
    if not isinstance(label, str):
        return _err("VALIDATION_ERROR", "label must be a string")
    if not (1 <= len(label) <= 128):
        return _err("VALIDATION_ERROR", "label length must be between 1 and 128")
    if not isinstance(quota_daily_requests, int):
        return _err("VALIDATION_ERROR", "quota_daily_requests must be an integer")
    if not (0 <= quota_daily_requests <= 100000000):
        return _err("VALIDATION_ERROR", "quota_daily_requests must be between 0 and 100000000")
    if not isinstance(quota_daily_compute_units, int):
        return _err("VALIDATION_ERROR", "quota_daily_compute_units must be an integer")
    if not (0 <= quota_daily_compute_units <= 1000000000):
        return _err("VALIDATION_ERROR", "quota_daily_compute_units must be between 0 and 1000000000")

    api_keys = _load("api_keys.json")

    # Generate a unique plaintext secret (returned once), prefix and hash.
    import secrets, hashlib
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ID convention: ak_<hex>
    def _new_id():
        return "ak_" + secrets.token_hex(16)

    # Prefix: first 8 chars of secret (client-visible, unique)
    # Hash: sha256(secret) - stored as hex
    # Must satisfy unique(key_hash) and unique(key_prefix)
    existing_hashes = {r.get("key_hash") for r in api_keys if isinstance(r, dict)}
    existing_prefixes = {r.get("key_prefix") for r in api_keys if isinstance(r, dict)}
    existing_ids = {r.get("id") for r in api_keys if isinstance(r, dict)}

    secret = None
    key_hash = None
    key_prefix = None
    for _ in range(50):
        candidate_secret = "calc_" + secrets.token_urlsafe(32)
        candidate_hash = hashlib.sha256(candidate_secret.encode("utf-8")).hexdigest()
        candidate_prefix = candidate_secret[:8]
        candidate_id = _new_id()
        if candidate_hash in existing_hashes:
            continue
        if candidate_prefix in existing_prefixes:
            continue
        if candidate_id in existing_ids:
            continue
        secret = candidate_secret
        key_hash = candidate_hash
        key_prefix = candidate_prefix
        new_id = candidate_id
        break
    if secret is None:
        return _err("CONFLICT", "Unable to generate a unique API key; please retry")

    row = {
        "id": new_id,
        "key_hash": key_hash,
        "key_prefix": key_prefix,
        "label": label,
        "status": "active",
        "quota_daily_requests": quota_daily_requests,
        "quota_daily_compute_units": quota_daily_compute_units,
        "created_at": now,
        "updated_at": now,
        "last_used_at": None
    }

    api_keys.append(row)
    _save("api_keys.json", api_keys)

    # Return plaintext secret exactly once as part of creation response
    # (not stored anywhere else).
    return {
        "api_key": dict(row),
        "secret": secret
    }

def update_api_key(id, label=None, quota_daily_requests=None, quota_daily_compute_units=None, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0274000" if __import__("os").path.isdir("./environment_mix/0274000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate id
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string")
    key_id = id.strip()

    # Validate optional fields
    if label is not None:
        if not isinstance(label, str):
            return _err("VALIDATION_ERROR", "label must be a string")
        if not (1 <= len(label) <= 128):
            return _err("VALIDATION_ERROR", "label length must be between 1 and 128")

    if quota_daily_requests is not None:
        if not isinstance(quota_daily_requests, int):
            return _err("VALIDATION_ERROR", "quota_daily_requests must be an integer")
        if not (0 <= quota_daily_requests <= 100000000):
            return _err("VALIDATION_ERROR", "quota_daily_requests must be between 0 and 100000000")

    if quota_daily_compute_units is not None:
        if not isinstance(quota_daily_compute_units, int):
            return _err("VALIDATION_ERROR", "quota_daily_compute_units must be an integer")
        if not (0 <= quota_daily_compute_units <= 1000000000):
            return _err("VALIDATION_ERROR", "quota_daily_compute_units must be between 0 and 1000000000")

    if label is None and quota_daily_requests is None and quota_daily_compute_units is None:
        return _err("VALIDATION_ERROR", "No fields provided to update")

    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []

    idx = None
    for i, r in enumerate(api_keys):
        if isinstance(r, dict) and r.get("id") == key_id:
            idx = i
            break
    if idx is None:
        return _err("NOT_FOUND", "API key not found", id=key_id)

    target = api_keys[idx]
    if not isinstance(target, dict):
        return _err("NOT_FOUND", "API key not found", id=key_id)

    status = target.get("status")
    if status == "revoked":
        # Tool description says INVALID_STATE; allowed error codes list does not include it.
        # Use INVALID_TRANSITION for "cannot mutate revoked".
        return _err("INVALID_TRANSITION", "Cannot update a revoked API key.", id=key_id)

    # Apply updates (no-op updates should still be persisted only if something actually changes)
    now_iso = _iso_now()
    new_row = dict(target)
    changed = False

    if label is not None and new_row.get("label") != label:
        new_row["label"] = label
        changed = True
    if quota_daily_requests is not None and new_row.get("quota_daily_requests") != quota_daily_requests:
        new_row["quota_daily_requests"] = quota_daily_requests
        changed = True
    if quota_daily_compute_units is not None and new_row.get("quota_daily_compute_units") != quota_daily_compute_units:
        new_row["quota_daily_compute_units"] = quota_daily_compute_units
        changed = True

    if not changed:
        # Idempotent: return current resource, but still "no success without effect" applies to mutations.
        # However, real APIs commonly treat identical updates as success; audit requirement is about matching no row.
        # Row matched; return as success without writing.
        return {"api_key": target}

    # Update audit timestamp
    new_row["updated_at"] = now_iso
    # created_at immutable: do not touch

    api_keys[idx] = new_row
    try:
        _save("api_keys.json", api_keys)
    except Exception:
        return _err("CONFLICT", "Failed to persist API key update.", id=key_id)

    return {"api_key": new_row}

def transition_api_key_status(id, status, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0274000" if __import__("os").path.isdir("./environment_mix/0274000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    if not isinstance(id, str) or not id:
        return _err("VALIDATION_ERROR", "id must be a non-empty string")
    if not isinstance(status, str):
        return _err("VALIDATION_ERROR", "status must be a string")
    if status not in ("active", "disabled", "revoked"):
        return _err("VALIDATION_ERROR", "status must be one of: active, disabled, revoked")

    api_keys = _load("api_keys.json")
    target = None
    for r in api_keys:
        if isinstance(r, dict) and r.get("id") == id:
            target = r
            break
    if target is None:
        return _err("NOT_FOUND", "API key not found", id=id)

    current = target.get("status")
    lifecycle = {
        "active": ["disabled", "revoked"],
        "disabled": ["active", "revoked"],
        "revoked": []
    }
    if current not in lifecycle:
        return _err("INVALID_TRANSITION", "API key has an invalid current status", id=id, current_status=current)

    if status == current:
        # Idempotent transition to same state: return current
        return {"api_key": dict(target)}

    if status not in lifecycle.get(current, []):
        return _err(
            "INVALID_TRANSITION",
            "Invalid status transition",
            id=id,
            from_status=current,
            to_status=status
        )

    target["status"] = status
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    target["updated_at"] = now

    _save("api_keys.json", api_keys)
    return {"api_key": dict(target)}
